def fruit_distribution(s, n):
    def extract_quantity(s):
        apples = 0
        oranges = 0
        for word in s.split():
            if word == 'apples':
                apples = int(s.split()[s.split().index(word) - 1])
            elif word == 'oranges':
                oranges = int(s.split()[s.split().index(word) - 1])
        return apples, oranges

    def calculate_mangoes(s, n):
        apples, oranges = extract_quantity(s)
        total_fruits = n
        mangoes = total_fruits - apples - oranges
        return mangoes

    return calculate_mangoes(s, n)

